<script setup lang="ts">
import { ui } from "../ui"
import { ref } from 'vue'
import { api,bootstrap,notify } from '../composables/api'
import { useCollaborationAction } from '../composables/collaboration'
import type { ErrorGroup } from '../types'
const props=defineProps<{issue:ErrorGroup}>(),emit=defineEmits<{changed:[]}>(),open=ref(false),query=ref(''),error=ref(''),loading=ref(false),saving=ref(false),candidates=ref<{key:string;label:string}[]>([])
const perform=useCollaborationAction()
async function search(){loading.value=true;error.value='';candidates.value=[];try{candidates.value=(await api<{items:{key:string;label:string}[]}>('/assignment-directory?q='+encodeURIComponent(query.value))).items}catch(e){error.value=e instanceof Error?e.message:'The host directory is unavailable.'}finally{loading.value=false}}
async function choose(key:string|null){saving.value=true;error.value='';try{await perform('/issues/'+props.issue.id+'/assignment','POST',{assignee:key,version:props.issue.state_version});open.value=false;notify(key?'Error assigned.':'Assignee cleared.');emit('changed')}catch(e){error.value=e instanceof Error?e.message:'Assignment failed. Reload the current error and try again.'}finally{saving.value=false}}
function toggle(){open.value=!open.value;if(open.value)search()}
</script>
<template><section :class="ui('$all', '$section', 'panel assignment-panel')"><h2 :class="ui('$all', '$h2')">Assignment</h2><p :class="ui('$all', '$p', 'assignee-label')">{{issue.assignee?.label??'Unassigned'}}</p><p v-if="issue.assignee&&issue.assignee.state!=='available'" :class="ui('$all', '$p', 'help')">The reference is retained. An operator can clear or replace it.</p><div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert"><p :class="ui('$all', '$p')">{{error}}</p><button :class="ui('$all', '$button', 'button')" :disabled="loading" @click="search">Retry directory</button></div><div v-if="bootstrap?.capabilities.operate" :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button')" :disabled="saving" :aria-expanded="open" @click="toggle">{{issue.assignee?'Change assignee':'Assign error'}}</button><button v-if="issue.assignee" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="choose(null)">Clear assignee</button></div><form v-if="open" :class="ui('$all', '$form', 'assignment-picker')" @submit.prevent="search"><label :class="ui('$all', '$label', 'field')">Search eligible host users<input :class="ui('$all', '$input')" v-model="query" :disabled="saving" placeholder="Name or host identity" maxlength="100"></label><button :class="ui('$all', '$button', 'button')" :disabled="loading||saving">{{loading?'Searching…':'Search directory'}}</button><ul :class="ui('$all', '$ul', 'candidate-list')"><li :class="ui('$all', '$li')" v-for="person in candidates" :key="person.key"><button :class="ui('$all', '$button', 'button')" type="button" :disabled="saving" @click="choose(person.key)">{{person.label}}</button></li></ul><p v-if="!loading&&!candidates.length" :class="ui('$all', '$p', 'help')">No eligible users returned.</p></form><p :class="ui('$all', '$p', 'help')">The host controls eligibility. Assigning an error does not grant dashboard access.</p></section></template>
